#!/usr/bin/env node
/**
 * Bundles the four IEP mock CSV files as TypeScript string modules so the app can
 * ship them without a native asset pipeline. The canonical files remain in
 * docs/iep-dashboard-agent-package/mock-data; re-run this script when they change.
 *
 *   node scripts/iep-bundle-mock-data.js
 */
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const source = path.join(root, 'docs', 'iep-dashboard-agent-package', 'mock-data');
const target = path.join(root, 'src', 'features', 'iep', 'mock', 'data');

const files = [
  ['IEP_dashboard_mock_summary_52_weeks.csv', 'summaryStandard'],
  ['IEP_dashboard_mock_events_52_weeks.csv', 'eventsStandard'],
  ['IEP_dashboard_mock_summary_edge_cases.csv', 'summaryEdgeCases'],
  ['IEP_dashboard_mock_events_edge_cases.csv', 'eventsEdgeCases'],
];

fs.mkdirSync(target, { recursive: true });

for (const [file, name] of files) {
  const csv = fs.readFileSync(path.join(source, file), 'utf8');
  const escaped = csv.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$\{/g, '\\${');
  const out = [
    '/* eslint-disable */',
    `// GENERATED by scripts/iep-bundle-mock-data.js from ${file}. Do not edit.`,
    '// Synthetic mock data for dashboard prototyping; not clinical data.',
    `const ${name}: string = \`${escaped}\`;`,
    `export default ${name};`,
    '',
  ].join('\n');
  fs.writeFileSync(path.join(target, `${name}.csv.ts`), out);
  console.log(`wrote ${name}.csv.ts (${csv.length} chars)`);
}
